INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Tarifverträge in der IT immer für alle gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für Tarifgebundene"}, {"text": "Ja", "correct": false, "because": "Nicht allgemeinverbindlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Vertrag für IT-Mitarbeiter prüfe?', 3, '[{"text": "Tarifbindung", "correct": true, "because": "Regelt Arbeitsbedingungen"}, {"text": "Schnelle Unterschrift", "correct": false, "because": "Inhalt zählt"}, {"text": "Design der Firma", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Tarifvertrag in der IT?', 5, '[{"text": "Gehaltsstufen", "correct": true, "because": "Regelt Vergütung"}, {"text": "Arbeitszeiten", "correct": true, "because": "Definiert Arbeitsumfang"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Tarifbestandteil"}, {"text": "Marketingpläne", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tarifverträge regeln Gruppeninteressen. b) Sie ersetzen Arbeitsverträge.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Arbeitsverträge bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Tarifvertrag für IT-Fachkräfte prüfe?', 4, '[{"text": "Geltungsbereich", "correct": false, "because": "Definiert Anwendung"}, {"text": "Rechtsverbindlichkeit", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Firmenfarben", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Betriebsvereinbarungen für alle ITler gelten?', 2, '[{"text": "Ja", "correct": true, "because": "Verbindlich im Betrieb"}, {"text": "Nein", "correct": false, "because": "Gilt für alle im Geltungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Tarifvertrag in der IT?', 3, '[{"text": "Einheitliche Bedingungen", "correct": true, "because": "Schafft Fairness"}, {"text": "Schnelle Projekte", "correct": false, "because": "Kein Tarifziel"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen einen Tarifvertrag in der IT nützlich?', 5, '[{"text": "Regelung von Überstunden", "correct": true, "because": "Schützt Mitarbeiter"}, {"text": "Mindestlöhne", "correct": true, "because": "Sichert Einkommen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Tarifbestandteil"}, {"text": "Bürodesign", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Betriebsvereinbarungen sind freiwillig. b) Sie regeln Arbeitszeiten. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Freiwilligkeit ist eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Tarifvertrag in der IT?', 4, '[{"text": "Gewerkschaft", "correct": false, "because": "Vertragspartei nötig"}, {"text": "Arbeitgeberverband", "correct": false, "because": "Tarifpartner nötig"}, {"text": "Farbkodierung", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Tarifverträge in der IT immer verpflichtend?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Tarifbindung"}, {"text": "Ja", "correct": false, "because": "Freiwillig möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Betriebsvereinbarung für IT-Teams?', 4, '[{"text": "Regelung von Homeoffice", "correct": true, "because": "Fördert Flexibilität"}, {"text": "Klarheit bei Arbeitszeiten", "correct": true, "because": "Schafft Struktur"}, {"text": "Höhere Gehälter", "correct": false, "because": "Tarifsache"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Tarifverträge nur große Firmen betreffen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Tarifgebundenen"}, {"text": "Ja", "correct": false, "because": "Auch kleine Firmen betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Arbeitsbedingungen für ITler zu regeln?', 3, '[{"text": "Betriebsvereinbarung", "correct": true, "because": "Betriebsspezifisch"}, {"text": "Einzelvertrag", "correct": false, "because": "Nicht kollektiv"}, {"text": "Firmendesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tarifverträge fördern Einheitlichkeit. b) Sie sind immer gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht gesetzlich zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen kollektive Verträge in der IT effektiv?', 5, '[{"text": "Verbindlichkeit", "correct": true, "because": "Sichert Umsetzung"}, {"text": "Klarheit", "correct": true, "because": "Vermeidet Streit"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Vertragsfaktor"}, {"text": "Bunte Büros", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Betriebsvereinbarung für ITler erstelle?', 3, '[{"text": "Regelungsbereich", "correct": false, "because": "Definiert Anwendung"}, {"text": "Beteiligung", "correct": false, "because": "Sichert Zustimmung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Tarifverträge Homeoffice regeln?', 3, '[{"text": "Ja", "correct": true, "because": "Arbeitsbedingungen umfassend"}, {"text": "Nein", "correct": false, "because": "Regelbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Betriebsvereinbarungen freiwillig sind?', 2, '[{"text": "Ja", "correct": true, "because": "Zwischen Parteien verhandelbar"}, {"text": "Nein", "correct": false, "because": "Freiwilligkeit gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für einen Tarifvertrag in der IT?', 4, '[{"text": "Tarifautonomie", "correct": true, "because": "Ermöglicht Verhandlungen"}, {"text": "Schnelle Unterschrift", "correct": false, "because": "Inhalt zählt"}, {"text": "Firmendeko", "correct": false, "because": "Irrelevant"}]');
